import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

solutions = []
for a in range(1, 11):
    target = 12 * a + 1

    # Find the integer root p such that p^a = target
    # We can use rounding for the a-th root, but must check the power
    p_approx = round(target**(1/a))

    # Check p_approx and potentially p_approx - 1 or p_approx + 1 due to floating point errors
    for p in range(max(2, p_approx - 2), p_approx + 3):
        if p**a == target:
            if is_prime(p):
                solutions.append((p, a))
            break # Found the base p, move to next a

print(solutions)

